ATTACH ':memory:' AS aux; CREATE TABLE aux.t1(a, b); INSERT INTO aux.t1 VALUES('a aux', 'b aux'); CREATE VIEW aux.v1 AS SELECT * FROM t1; CREATE VIEW aux.v2 AS SELECT * FROM t1; CREATE VIEW aux.v3 AS SELECT * FROM t1; CREATE TEMP TABLE t1(a, b); INSERT INTO temp.t1 VALUES('a temp', 'b temp'); CREATE VIEW temp.v1 AS SELECT * FROM t1; DROP VIEW v1; INSERT INTO main.view_log SELECT 'main', name FROM main.sqlite_schema WHERE type='view' UNION ALL SELECT 'temp', name FROM temp.sqlite_schema WHERE type='view' UNION ALL SELECT 'aux', name FROM aux.sqlite_schema WHERE type='view';